        int first = 1;
        for (uint32_t j = 0; j < i; j++) if (nb_la[j] == nb_la[i] && nb_ls[j] == nb_ls[i]) { first = 0; break; }
        if (!first) continue;
        const uint8_t *p = f_ramp(e, nb_la[i], nb_ls[i]);
        if (!p) return 0;
